(() => {
  const brandLogo = 'data:image/png;base64,';
    const udSymbol = 'data:image/png;base64,';   if (mark) mark.src = udSymbol;
  document.querySelectorAll('.brand img').forEach(image => { image.addEventListener('error', () => { image.src = brandLogo; }, { once: true }); });
  const accessBrand = document.querySelector('.access-brand');
  if (accessBrand) accessBrand.addEventListener('error', () => { accessBrand.src = brandLogo; }, { once: true });
  const mark = document.querySelector('.community-mark img');
  if (mark) mark.addEventListener('error', () => { mark.src = udSymbol; }, { once: true });
})();